const alternateHomes=['nevera-vintage'];
const vintageTypography={font:'serif',size:'mediano',weight:'normal'};
const openedFridgeDoors=new Set();
function usesVintageHome(){
 return $('items').dataset.home==='nevera-vintage';
}
function applyAlternateHome(value){
 const home=alternateHomes.includes(value)?value:'';
 $('items').dataset.home=home;
 const toolbar=$('toolbar');
 $('search').placeholder=home==='nevera-vintage'?'Buscar alimentos…':'🔎 Buscar alimentos…';
 if(home==='nevera-vintage')$('fridgeControls').append(toolbar);
 else $('items').before(toolbar);
 if(home==='nevera-vintage')$('search').before(switchPantry);
 else $('adminPanel').before(switchPantry);
 updatePantrySwitchLabel();
 $('alternateHome').checked=!!home;
 $('startFridgeClosed').checked=pantryStylePreference('start_fridge_closed')===true;
 $('startFridgeClosed').disabled=!home;
 syncFridgeNotesSetting();
 const vintage=usesVintageHome();
 applyTypography(vintage?(pantryStylePreference('vintage_list_typography')??vintageTypography):pantryStylePreference('list_typography'));
 applyPantryIconSize(pantryStylePreference(vintage?'vintage_pantry_icon_size':'pantry_icon_size'));
 applyIconFamily(pantryStylePreference('icon_family'),pantryStylePreference('admin_icon_family'));
 syncWeatherStation();
}
$('alternateHome').onchange=async event=>{
 const checkbox=event.currentTarget;
 const current=session;
 if(!current)return;
 const home=checkbox.checked?alternateHomes[0]:null;
 const message=$('alternateHomeMessage');
 checkbox.disabled=true;
 $('startFridgeClosed').disabled=true;
 $('enableFridgeNotes').disabled=$('enableAutomaticPantryNote').disabled=true;
 message.textContent='Guardando página de inicio…';
 try{
  const {data:result,error}=await db.auth.updateUser({data:{[pantryStyleKey('alternate_home')]:home??''}});
  if(error)throw error;
  if(session!==current)return;
  current.user=result.user;
  applyAlternateHome(pantryStylePreference('alternate_home'));
  render();
  message.textContent='Página de inicio guardada en tu cuenta.';
 }catch(error){
  if(session!==current)return;
  applyAlternateHome(pantryStylePreference('alternate_home'));
  message.textContent='No se pudo guardar la página de inicio: '+error.message;
 }finally{
  checkbox.disabled=false;
 }
};
$('startFridgeClosed').onchange=async event=>{
 const checkbox=event.currentTarget;
 const current=session;
 if(!current)return;
 const message=$('alternateHomeMessage');
 checkbox.disabled=true;
 $('alternateHome').disabled=true;
 $('enableFridgeNotes').disabled=$('enableAutomaticPantryNote').disabled=true;
 message.textContent='Guardando apertura de la nevera…';
 try{
  const {data:result,error}=await db.auth.updateUser({data:{[pantryStyleKey('start_fridge_closed')]:checkbox.checked}});
  if(error)throw error;
  if(session!==current)return;
  current.user=result.user;
  openedFridgeDoors.clear();
  render();
  message.textContent='Apertura de la nevera guardada.';
 }catch(error){
  if(session!==current)return;
  checkbox.checked=pantryStylePreference('start_fridge_closed')===true;
  message.textContent='No se pudo guardar la apertura de la nevera: '+error.message;
 }finally{
  checkbox.disabled=!usesVintageHome();
  $('alternateHome').disabled=false;
  syncFridgeNotesSetting();
 }
};

const fridgeNoteSettings={
 enableFridgeNotes:'fridge_notes_enabled',
 enableAutomaticPantryNote:'automatic_pantry_note_enabled'
};
function syncFridgeNotesSetting(){
 for(const [id,key] of Object.entries(fridgeNoteSettings)){
  const setting=$(id);
  setting.disabled=!usesVintageHome()||!$('startFridgeClosed').checked;
  setting.checked=pantryStylePreference(key)===true;
 }
}
for(const [id,key] of Object.entries(fridgeNoteSettings))$(id).onchange=async event=>{
 const setting=event.currentTarget;
 const current=session;
 if(!current||setting.disabled)return;
 const home=$('alternateHome');
 const doors=$('startFridgeClosed');
 const status=$('alternateHomeMessage');
 home.disabled=doors.disabled=true;
 for(const id of Object.keys(fridgeNoteSettings))$(id).disabled=true;
 try{
  const {data:result,error}=await db.auth.updateUser({data:{[pantryStyleKey(key)]:setting.checked}});
  if(error)throw error;
  if(session!==current)return;
  current.user=result.user;
  status.textContent='Preferencia de notas guardada.';
  render();
 }catch(error){
  if(session===current)status.textContent='No se pudo guardar la preferencia: '+error.message;
 }finally{
  home.disabled=false;
  doors.disabled=!usesVintageHome();
  syncFridgeNotesSetting();
 }
};

const fridgeNoteDialog=$('fridgeNoteDialog');
const fridgeNotePreview=$('fridgeNotePreview');
const fridgeNoteRows=$('fridgeNoteRows');
const fridgeNoteAdd=$('fridgeNoteAdd');
const fridgeNoteSave=$('fridgeNoteSave');
const defaultPersonalNoteTags=Object.freeze([
 'Supermercado 1','Supermercado 2','Frutería','Carnicería','Panadería',
 'Pescadería','Farmacia','Ferretería','Mercado','Bazar'
]);
const noteTagMetadataKey='personal_note_tags';
// Sustituir los nombres antiguos incluso en cuentas y notas que ya los guardaron.
const renamedPersonalNoteTags=Object.freeze({'Lidl':'Supermercado 1','Mercadona':'Supermercado 2'});
const normalizePersonalNoteTag=tag=>renamedPersonalNoteTags[tag.trim()]??tag.trim();
function configuredPersonalNoteTags(pantryId=typeof activePantry==='undefined'?null:activePantry?.id){
 const preferences=session?.user?.user_metadata;
 const pantryTags=pantryId&&preferences?.[noteTagMetadataKey+'_'+pantryId];
 const stored=pantryTags??preferences?.[noteTagMetadataKey];
 const tags=Array.isArray(stored)?stored:defaultPersonalNoteTags;
 const literal=Array.isArray(pantryTags)||preferences?.personal_note_tags_literal===true;
 return [...new Set(tags.filter(tag=>typeof tag==='string'&&tag.trim())
  .map(tag=>literal?tag.trim():normalizePersonalNoteTag(tag)))];
}
function selectedPersonalNoteTags(note){
 return Array.isArray(note?.tags)
  ?[...new Set(note.tags.filter(tag=>typeof tag==='string'&&tag.trim()).map(tag=>note.tagsLiteral?tag.trim():normalizePersonalNoteTag(tag)))]
  :[];
}
// El primer TAG es un título de reserva: un título escrito por el usuario tiene prioridad.
function personalNoteDisplayTitle(note){
 const title=typeof note?.title==='string'?note.title.trim():'';
 return title||selectedPersonalNoteTags(note)[0]||'Nota '+note.number;
}
let savingPersonalNoteTags=false;
function renderAdminNoteTags(){
 const list=$('adminNoteTags');
 list.replaceChildren();
 const tags=configuredPersonalNoteTags();
 for(const [index,tag] of tags.entries()){
  const row=document.createElement('div');
  row.className='admin-note-tag-row';
  const name=document.createElement('strong');
  name.className='admin-note-tag-name';
  name.textContent=tag;
  const buttons=document.createElement('div');
  buttons.className='admin-note-tag-actions';
  for(const [delta,icon,label] of [[-1,'up','Subir'],[1,'down','Bajar']]){
   const button=document.createElement('button');
   button.type='button';
   setAdminIcon(button,icon,label+' etiqueta '+tag);
   button.classList.add('secondary');
   button.disabled=savingPersonalNoteTags||index+delta<0||index+delta>=tags.length;
   button.onclick=()=>{
    const next=[...configuredPersonalNoteTags()];
    const currentIndex=next.indexOf(tag);
    const targetIndex=currentIndex+delta;
    if(currentIndex<0||targetIndex<0||targetIndex>=next.length)return;
    [next[currentIndex],next[targetIndex]]=[next[targetIndex],next[currentIndex]];
    savePersonalNoteTags(next,'Orden de etiquetas guardado.');
   };
   buttons.append(button);
  }
  const edit=document.createElement('button');
  edit.type='button';
  edit.className='secondary';
  setAdminIcon(edit,'edit','Editar etiqueta '+tag);
  edit.disabled=savingPersonalNoteTags;
  edit.onclick=()=>{
   if(row.querySelector('.admin-note-tag-edit'))return;
   const form=document.createElement('form');
   form.className='admin-note-tag-edit';
   const input=document.createElement('input');
   input.type='text';
   input.maxLength=30;
   input.required=true;
   input.value=tag;
   input.setAttribute('aria-label','Nuevo nombre para '+tag);
   const save=document.createElement('button');
   save.type='submit';
   save.textContent='Guardar';
   const cancel=document.createElement('button');
   cancel.type='button';
   cancel.className='secondary';
   cancel.textContent='Cancelar';
   cancel.onclick=()=>{form.remove();edit.focus();};
   form.onsubmit=event=>{
    event.preventDefault();
    const value=input.value.trim().replace(/\s+/g,' ');
    if(!value)return;
    const current=configuredPersonalNoteTags();
    if(current.some(other=>other!==tag&&folded(other)===folded(value))){
     $('noteTagsStatus').textContent='Ya existe una etiqueta con ese nombre.';
     input.focus();
     return;
    }
    if(value===tag){form.remove();edit.focus();return;}
    savePersonalNoteTags(current.map(other=>other===tag?value:other),'Etiqueta modificada.');
   };
   form.append(input,save,cancel);
   row.append(form);
   input.focus();
   input.select();
  };
  const remove=document.createElement('button');
  remove.type='button';
  remove.className='danger';
  setAdminIcon(remove,'trash','Eliminar etiqueta '+tag);
  remove.disabled=savingPersonalNoteTags;
  remove.onclick=()=>{
   if(!confirm('¿Eliminar «'+tag+'» del catálogo de etiquetas? Las notas existentes se conservarán.'))return;
   savePersonalNoteTags(configuredPersonalNoteTags().filter(value=>value!==tag),'Etiqueta eliminada.');
  };
  buttons.append(edit,remove);
  row.append(name,buttons);
  list.append(row);
 }
 $('noteTagAdd').disabled=savingPersonalNoteTags;
 $('noteTagInput').disabled=savingPersonalNoteTags;
}
async function savePersonalNoteTags(tags,message){
 if(!session||savingPersonalNoteTags)return false;
 const current=session;
 savingPersonalNoteTags=true;
 $('noteTagsStatus').textContent='Guardando etiquetas…';
 renderAdminNoteTags();
 try{
  const scopedKey=pantryStyleKey(noteTagMetadataKey);
  const updates=Array.isArray(current.user.user_metadata?.[scopedKey])?
   {[scopedKey]:tags}:{[noteTagMetadataKey]:tags,personal_note_tags_literal:true};
  const {data:result,error}=await db.auth.updateUser({data:updates});
  if(error)throw error;
  if(session!==current)return false;
  current.user=result.user;
  $('noteTagsStatus').textContent=message;
  $('noteTagInput').value='';
  return true;
 }catch(error){
  if(session===current)$('noteTagsStatus').textContent='No se pudieron guardar las etiquetas: '+error.message;
  return false;
 }finally{
  savingPersonalNoteTags=false;
  if(session===current)renderAdminNoteTags();
 }
}
setAdminIcon($('noteTagAdd'),'add','Añadir etiqueta');
$('noteTagForm').onsubmit=event=>{
 event.preventDefault();
 const input=$('noteTagInput');
 const value=input.value.trim().replace(/\s+/g,' ');
 if(!value||savingPersonalNoteTags)return;
 const current=configuredPersonalNoteTags();
 if(current.some(tag=>folded(tag)===folded(value))){
  $('noteTagsStatus').textContent='Esa etiqueta ya existe.';
  input.focus();return;
 }
 savePersonalNoteTags([...current,value],'Etiqueta añadida.');
};
function renderPersonalNoteTagCloud(note,persist){
 const cloud=$('fridgeNoteTagCloud');
 cloud.replaceChildren();
 const selected=selectedPersonalNoteTags(note);
 const configured=configuredPersonalNoteTags();
 const all=[...configured,...selected.filter(tag=>!configured.includes(tag))];
 for(const tag of all){
  const chip=document.createElement('button');
  chip.type='button';
  chip.className='personal-note-tag';
  const active=selected.includes(tag);
  if(!configured.includes(tag))chip.classList.add('is-retired-tag');
  chip.setAttribute('aria-pressed',String(active));
  chip.setAttribute('aria-label',(active?'Quitar etiqueta ':'Añadir etiqueta ')+tag);
  chip.title=active?'Quitar etiqueta '+tag:'Añadir etiqueta '+tag;
  chip.textContent=tag;
  chip.onclick=()=>{
   const next=active?selected.filter(value=>value!==tag):[...selected,tag];
   if(persist(next)){
    note.tags=next;
    renderPersonalNoteTagCloud(note,persist);
   }
  };
  cloud.append(chip);
 }
}

