function positionFridgeNoteEditor(){
 if(!fridgeNoteDialog.open||!fridgeNoteDialog.classList.contains('note-editing'))return;
 const viewport=window.visualViewport;
 fridgeNoteDialog.style.setProperty('--note-viewport-top',(viewport?.offsetTop??0)+'px');
 fridgeNoteDialog.style.setProperty('--note-viewport-height',(viewport?.height??window.innerHeight)+'px');
}
window.visualViewport?.addEventListener('resize',positionFridgeNoteEditor);
window.visualViewport?.addEventListener('scroll',positionFridgeNoteEditor);
window.addEventListener('resize',positionFridgeNoteEditor);
function appendFridgeNoteRow({name='',quantity=''}={}){
 const row=document.createElement('div');
 row.className='note-row';
 const food=document.createElement('input');
 food.type='text';
 food.placeholder='Alimento';
 food.setAttribute('aria-label','Alimento');
 food.value=name;
 const amount=document.createElement('input');
 amount.type='text';
 amount.placeholder='Cant.';
 amount.setAttribute('aria-label','Cantidad');
 amount.value=quantity;
 const remove=document.createElement('button');
 remove.type='button';
 remove.textContent='×';
 remove.setAttribute('aria-label','Quitar alimento');
 remove.onclick=()=>{
  const next=row.nextElementSibling||row.previousElementSibling;
  row.remove();
  (next?.firstElementChild||fridgeNoteAdd).focus();
 };
 row.append(food,amount,remove);
 fridgeNoteRows.append(row);
 row.onkeydown=event=>{
  if(event.key!=='Enter'||event.isComposing||event.target===remove)return;
  event.preventDefault();
  (row.nextElementSibling?.firstElementChild||appendFridgeNoteRow()).focus();
 };
 return food;
}
fridgeNoteAdd.onclick=()=>appendFridgeNoteRow().focus();

function renderFridgeNotes(main,groupOrder,allDoorsClosed){
 const key='hondadespensa:notes:'+session.user.id+':'+activePantry.id;
 let notes=[];
 try{notes=JSON.parse(localStorage.getItem(key))??[];}catch{}
 function save(next){
  try{localStorage.setItem(key,JSON.stringify(next));notes=next;return true;}
  catch{alert('No se pudieron guardar las notas en este dispositivo.');return false;}
 }
 const layer=document.createElement('div');
 layer.className='fridge-notes';
 layer.classList.toggle('fridge-notes-tray',!allDoorsClosed);
 if(allDoorsClosed)main.append(layer);
 else main.prepend(layer);
 const doors=[...main.querySelectorAll(':scope > .fridge-door')];
 const size=52;
 const surfaceWidth=()=>allDoorsClosed?layer.clientWidth:main.clientWidth-4;
 function doorLayout(){
  if(allDoorsClosed){
   const origin=layer.getBoundingClientRect().top;
   return doors.map(door=>{
    const {top,bottom}=door.getBoundingClientRect();
    return {top:top-origin,bottom:bottom-origin};
   });
  }
  // Al añadir desde la bandeja, busca un hueco en la superficie de las puertas cerradas.
  const style=getComputedStyle(main);
  const gap=parseFloat(style.getPropertyValue('--fridge-door-gap'));
  let top=0;
  return groupOrder.map(group=>{
   const shape=groupOrder.length===1?'single':group;
   const [w,h]=style.getPropertyValue('--fridge-door-'+shape+'-ratio').split('/').map(Number);
   const bottom=top+surfaceWidth()*h/w;
   const bounds={top,bottom};
   top=bottom+gap;
   return bounds;
  });
 }
 const dimensions=(layout)=>[
  Math.max(1,surfaceWidth()-size),
  Math.max(1,(allDoorsClosed?layer.clientHeight:(layout??doorLayout()).at(-1).bottom)-size)
 ];
 let blue;
 let controls;
 function attachNote(button,note,commit,open){
  if(!allDoorsClosed){
   button.onclick=open;
   return;
  }
  function position(x,y){
   button.style.left='calc('+100*x+'% - '+size*x+'px)';
   button.style.top='calc('+100*y+'% - '+size*y+'px)';
  }
  position(note.x,note.y);
  let drag;
  let suppressClick=false;
  button.onpointerdown=event=>{
   if(event.button!==0||!event.isPrimary)return;
   suppressClick=false;
   drag={id:event.pointerId,x:event.clientX,y:event.clientY};
   button.setPointerCapture(event.pointerId);
  };
  button.onpointermove=event=>{
   if(drag?.id!==event.pointerId)return;
   const dx=event.clientX-drag.x,dy=event.clientY-drag.y;
   if(!drag.moved&&Math.hypot(dx,dy)<5)return;
   const [width,height]=dimensions();
   if(!drag.moved){
    layer.querySelector('.fridge-note-on-top')?.classList.remove('fridge-note-on-top');
    button.classList.add('fridge-note-on-top');
   }
   drag.moved=true;
   drag.nx=Math.min(1,Math.max(0,note.x+dx/width));
   drag.ny=Math.min(1,Math.max(0,note.y+dy/height));
   position(drag.nx,drag.ny);
  };
  button.onpointerup=event=>{
   if(drag?.id!==event.pointerId)return;
   const {moved,nx,ny}=drag;
   drag=null;
   suppressClick=moved;
   if(moved&&free(nx,ny,note.number)&&commit(nx,ny)){
    note.x=nx;
    note.y=ny;
   }else position(note.x,note.y);
  };
  button.onpointercancel=()=>{drag=null;position(note.x,note.y);};
  button.onclick=event=>{
   if(suppressClick&&event.detail){suppressClick=false;return;}
   open();
  };
 }
 if(pantryStylePreference('automatic_pantry_note_enabled')===true){
  const button=document.createElement('button');
  button.type='button';
  button.className='fridge-note fridge-pantry-note';
  button.textContent='✓';
  button.setAttribute('aria-label','Abrir lista de la compra');
  layer.append(button);
  const [width,height]=dimensions();
  blue={number:0,x:12/width,y:9/height};
  try{Object.assign(blue,JSON.parse(localStorage.getItem(key+':blue')));}catch{}
  attachNote(button,blue,(x,y)=>{
   try{localStorage.setItem(key+':blue',JSON.stringify({x,y}));return true;}
   catch{return false;}
  },()=>{
   $('automaticPantryNoteDialog').classList.remove('personal-note-summary');
   $('automaticPantryNoteTitle').textContent='Lista de la compra';
   const missing={dry:[],fresh:[]};
   for(const food of data){
    if(!food.have&&isFoodGroupVisible(isFreshCategory(food.category)?'fresh':'dry'))
    missing[isFreshCategory(food.category)?'fresh':'dry'].push(food);
   }
   const list=$('automaticPantryNoteList');
   list.replaceChildren();
   const order=foodGroupOrder.value==='fresh'?['fresh','dry']:['dry','fresh'];
   for(const group of order){
    if(!missing[group].length)continue;
    const title=document.createElement('h3');
    title.textContent=group==='fresh'?'Alimentos frescos':'Alimentos secos';
    const rows=document.createElement('ul');
    for(const food of missing[group].sort((a,b)=>esCompare(a.name,b.name))){
     const row=document.createElement('li');
     row.className='note-row';
     row.textContent=food.name;
     rows.append(row);
    }
    list.append(title,rows);
   }
   if(!list.childElementCount)list.textContent='No faltan alimentos.';
   $('automaticPantryNoteDialog').showModal();
  });
 }
 if(pantryStylePreference('fridge_notes_enabled')!==true)return;
 controls=$('fridgeNoteControlsTemplate').content.firstElementChild.cloneNode(true);
 const [add,summary,deleteAll]=controls.querySelectorAll('button');
 const deleteDivider=deleteAll.previousElementSibling;
 layer.append(controls);
 summary.onclick=()=>{
  const dialog=$('automaticPantryNoteDialog');
  dialog.classList.add('personal-note-summary');
  $('automaticPantryNoteTitle').textContent='Resumen de notas';
  const list=$('automaticPantryNoteList');
  list.replaceChildren();
  for(const note of notes){
   const title=document.createElement('h3');
   title.textContent=personalNoteDisplayTitle(note);
   const rows=document.createElement('ul');
   const items=note.items??(note.message??'').split(/\r?\n/).filter(line=>line.trim()).map(name=>({name}));
   for(const item of items){
    const row=document.createElement('li');
    row.className='note-row';
    row.textContent=[item.name,item.quantity].filter(Boolean).join(' · ');
    rows.append(row);
   }
   const tags=selectedPersonalNoteTags(note);
   if(tags.length){
    const badge=document.createElement('small');
    badge.className='personal-note-tags-summary';
    badge.textContent=tags.join(' · ');
    title.append(badge);
   }
   list.append(title,rows);
  }
  if(!notes.length)list.textContent='Aún no hay notas personales.';
  dialog.showModal();
 };

 deleteAll.onclick=()=>{
  if(notes.length<2||!confirm('¿Borrar las '+notes.length+' notas personales de esta despensa?'))return;
  if(save([])){draw();add.focus();}
 };

 function draw(){
  const hasMultipleNotes=notes.length>1;
  summary.hidden=summary.previousElementSibling.hidden=!hasMultipleNotes;
  deleteAll.hidden=deleteDivider.hidden=!hasMultipleNotes;
  layer.querySelectorAll('.fridge-note:not(.fridge-pantry-note)').forEach(button=>button.remove());
  for(const note of notes){
   const button=document.createElement('button');
   button.type='button';
   button.className='fridge-note';
   button.textContent=note.number;
   button.setAttribute('aria-label','Abrir nota '+note.number);
   if(note.createdAt){
    const date=document.createElement('time');
    date.dateTime=note.createdAt;
    date.textContent=new Date(note.createdAt).toLocaleDateString('es-ES',{day:'2-digit',month:'2-digit'});
    button.append(date);
   }
   attachNote(button,note,(x,y)=>save(notes.map(item=>item.number===note.number?{...item,x,y}:item)),()=>{
    const savedNote=notes.find(item=>item.number===note.number);
    const titleButton=$('fridgeNoteEditTitle');
    const titleInput=$('fridgeNoteTitleInput');
    titleButton.textContent=personalNoteDisplayTitle(savedNote);
    renderPersonalNoteTagCloud(savedNote,next=>{
     const saved=save(notes.map(item=>item.number===note.number?{...item,tags:next,tagsLiteral:true}:item));
     if(saved){
      savedNote.tags=next;
      savedNote.tagsLiteral=true;
      titleButton.textContent=personalNoteDisplayTitle(savedNote);
      titleInput.placeholder=personalNoteDisplayTitle(savedNote);
     }
     return saved;
    });
    titleButton.hidden=false;
    titleInput.value=savedNote.title||'';
    titleInput.placeholder=personalNoteDisplayTitle(savedNote);
    titleInput.hidden=true;
    titleButton.onclick=()=>{
     titleButton.hidden=true;
     titleInput.hidden=false;
     fridgeNoteDialog.classList.add('note-editing');
     fridgeNoteSave.hidden=false;
     positionFridgeNoteEditor();
     titleInput.focus();
    };
    const items=savedNote.items??savedNote.message.split(/\r?\n/).filter(line=>line.trim()).map(name=>({name,quantity:''}));
    fridgeNotePreview.replaceChildren();
    fridgeNoteRows.replaceChildren();
    const fields=items.map(appendFridgeNoteRow);
    for(const [index,item] of items.entries()){
     const row=document.createElement('button');
     row.type='button';
     row.className='note-row';
     const name=document.createElement('span');
     name.textContent=item.name;
     const quantity=document.createElement('span');
     quantity.textContent=item.quantity;
     row.append(name,quantity);
     row.onclick=()=>edit(fields[index]);
     fridgeNotePreview.append(row);
    }
    if(!items.length){
     const empty=document.createElement('button');
     empty.type='button';
     empty.textContent='Toca para añadir un alimento';
     empty.onclick=()=>edit(appendFridgeNoteRow());
     fridgeNotePreview.append(empty);
    }
    function edit(field){
     fridgeNoteDialog.classList.add('note-editing');
     fridgeNotePreview.hidden=true;
     fridgeNoteRows.hidden=false;
     fridgeNoteAdd.hidden=false;
     fridgeNoteSave.hidden=false;
     positionFridgeNoteEditor();
     field.focus();
    }
    fridgeNoteDialog.classList.remove('note-editing');
    fridgeNotePreview.hidden=false;
    fridgeNoteRows.hidden=true;
    fridgeNoteAdd.hidden=true;
    fridgeNoteSave.hidden=true;
    fridgeNoteSave.onclick=()=>{
     const items=Array.from(fridgeNoteRows.children,row=>({
      name:row.children[0].value.trim(),
      quantity:row.children[1].value.trim()
     })).filter(item=>item.name);
     const message=items.map(item=>item.name).join('\n');
     if(save(notes.map(item=>item.number===note.number?{...item,items,message,title:titleInput.value.trim()}:item)))fridgeNoteDialog.close();
    };
    $('fridgeNoteDelete').onclick=()=>{
     if(save(notes.filter(item=>item.number!==note.number))){fridgeNoteDialog.close();draw();add.focus();}
    };
    fridgeNoteDialog.showModal();
   });
   layer.append(button);
  }
 }
 function free(x,y,number,layout=doorLayout()){
  const [width,height]=dimensions(layout);
  const left=x*width,top=y*height;
  if(!layout.some(door=>top>=door.top&&top+size<=door.bottom))return false;
  if(controls){
   const buttons=[...controls.querySelectorAll('button:not([hidden])')];
   const controlLeft=allDoorsClosed?controls.offsetLeft:width+size-8-Math.max(...buttons.map(button=>button.offsetWidth));
   const controlBottom=allDoorsClosed?controls.offsetTop+controls.offsetHeight
    :5+buttons.reduce((height,button)=>height+button.offsetHeight,0)+2*(buttons.length-1);
   if(left+size>controlLeft&&top<controlBottom)return false;
  }
  const maxOverlap=number===undefined?5:22;
  return [...notes,...(blue?[blue]:[])].every(note=>note.number===number||
   Math.abs(note.x-x)*width>=size-maxOverlap||Math.abs(note.y-y)*height>=size-maxOverlap);
 }
 add.onclick=()=>{
  const number=Math.max(0,...notes.map(note=>note.number))+1;
  const layout=doorLayout();
  const [width,height]=dimensions(layout);
  const area=Math.min(height,Math.max(0,layout[0].bottom-size));
  for(let y=Math.round(area*.49);y<=height;y+=size-5){
   for(let x=Math.round(width*.25);x<=width*.86;x+=size-5){
    if(!free(x/width,y/height,undefined,layout))continue;
    if(save([...notes,{number,message:'',createdAt:new Date().toISOString(),x:x/width,y:y/height}])){
     draw();
     const newNoteButton=layer.lastElementChild;
     newNoteButton.focus();
     newNoteButton.click();
    }
    return;
   }
  }
  alert('Mueve o elimina alguna nota para hacer sitio.');
 };
 draw();
}

function showApp(visible){
 if(!visible)adminMode=false;
 $('pantryFooter').hidden=!visible||adminMode;
 switchPantry.hidden=!visible||adminMode||(!usesVintageHome()&&availablePantries.length<2);
 const adminToggle=$('adminToggle');
 if(adminMode)$('adminPanel').prepend(adminToggle);
 else $('pantryFooter').append(adminToggle);
 adminToggle.setAttribute('aria-label',adminMode?'Volver a despensa':'Administrar');
 adminToggle.innerHTML=adminMode?'← Volver a despensa':'<span aria-hidden="true">&#9881;&#65038;</span>';
 $('adminPanel').hidden=!visible||!adminMode;
 for(const id of ['stats','toolbar','items'])$(id).hidden=!visible||adminMode;
 syncWeatherStation();
 $('auth').hidden=visible;
 $('loginForm').hidden=visible;
 $('status').hidden=visible;
 if(!visible)$('migration').hidden=true;
}
// Preferencias visuales independientes por cuenta y despensa; no se borran datos.
const foodGroupVisibility={dry:true,fresh:true};
const isFoodGroupVisible=group=>foodGroupVisibility[group]!==false;
function syncFoodGroupVisibility(){
 for(const group of ['dry','fresh']){
  foodGroupVisibility[group]=pantryStylePreference('show_'+group+'_foods')!==false;
 }
}
let savingFoodGroupVisibility=false;
async function saveFoodGroupVisibility(group,visible){
 if(!session||!activePantry||savingFoodGroupVisibility||!['dry','fresh'].includes(group))return;
 const current=session,pantry=activePantry,previous=isFoodGroupVisible(group);
 if(previous===visible)return;
 savingFoodGroupVisibility=true;
 foodGroupVisibility[group]=visible;
 render();
 try{
  const {data:result,error}=await db.auth.updateUser({
   data:{[pantryStyleKey('show_'+group+'_foods')]:visible}
  });
  if(error)throw error;
  if(session===current&&activePantry===pantry){
   current.user=result.user;
   adminMessage((visible?'Mostrando ':'Ocultando ')+(group==='dry'?'alimentos secos.':'alimentos frescos.'));
  }
 }catch(error){
  if(session===current&&activePantry===pantry){
   foodGroupVisibility[group]=previous;
   adminMessage('No se pudo guardar la visibilidad: '+error.message);
  }
 }finally{
  savingFoodGroupVisibility=false;
  if(session===current&&activePantry===pantry)render();
 }
}
const foodGroupOrder=$('foodGroupOrder');
function foodGroupOrderKey(){
 return 'hondadespensa:food-group-order:'+session?.user?.id+':'+activePantry?.id;
}
let visibleFoodGroup;
foodGroupOrder.onchange=()=>{
 visibleFoodGroup=undefined;
 try{localStorage.setItem(foodGroupOrderKey(),foodGroupOrder.value);}catch{}
 render();
};
function isFreshCategory(category){
 const row=pantryCategoryByName.get(category);
 return Object.hasOwn(freshCategoryArt,row?.icono)
  || [category,...(row?.nombres_anteriores??[])].some(name=>freshCategoryIcon(name));
}
function closeFridgeFromRightEdge(event){
 if(event.defaultPrevented||event.button!==0||event.detail===0)return;
 const distanceFromRight=document.documentElement.clientWidth-event.clientX;
 if(distanceFromRight<0||distanceFromRight>24)return;
 const list=$('categoryList');
 if($('items').hidden||!list.classList.contains('fridge-with-doors'))return;
 if(event.target.closest('button,input,select,textarea,label,summary,a,form,dialog,.item,[contenteditable]'))return;
 // En una nevera combi, la altura del toque identifica la puerta.
 for(const compartment of list.querySelectorAll(':scope > .fridge-compartment')){
  const {top,bottom}=compartment.getBoundingClientRect();
  if(event.clientY>=top&&event.clientY<bottom){
   compartment.querySelector('.fridge-close-door')?.click();
   return;
  }
 }
}
document.addEventListener('click',closeFridgeFromRightEdge);

const homeCardRemoval=$('enableHomeCardRemoval');
function homeCardRemovalKey(){
 return 'hondadespensa:eliminar-tarjetas:'+session.user.id;
}
function restoreHomeCardRemoval(){
 homeCardRemoval.checked=false;
 try{
  const key=homeCardRemovalKey();
  const saved=localStorage.getItem(key);
  homeCardRemoval.checked=saved===null
   ?availablePantries.some(pantry=>localStorage.getItem(key+':'+pantry.id)==='true')
   :saved==='true';
  if(saved===null&&homeCardRemoval.checked)localStorage.setItem(key,'true');
 }catch{}
}
homeCardRemoval.onchange=()=>{
 if(!session)return;
 try{localStorage.setItem(homeCardRemovalKey(),String(homeCardRemoval.checked));}catch{}
};

function render(){
 const q=folded($('search').value.trim());
 const visibleData=data.filter(x=>isFoodGroupVisible(isFreshCategory(x.category)?'fresh':'dry'));
 $('total').textContent=visibleData.length;
 $('have').textContent=visibleData.filter(x=>x.have).length;
 $('missing').textContent=visibleData.filter(x=>!x.have).length;
 const vintage=usesVintageHome();
 const shown=(vintage?visibleData:data).filter(x=>folded(x.name).includes(q));
 const categoriesWithStock=new Set(data.filter(item=>item.have).map(item=>item.category));
 const main=$('categoryList');main.replaceChildren();
 if(vintage&&!shown.length){
  const p=document.createElement('p');p.className='empty';
  p.textContent=!isFoodGroupVisible('dry')&&!isFoodGroupVisible('fresh')
   ?'Has ocultado ambos grupos. Puedes volver a mostrarlos en Administración.'
   :'No hay alimentos con este filtro.';
  main.append(p);
 }
 const categories=orderedCategories(pantryCategories())
  .filter(category=>!vintage||isFoodGroupVisible(isFreshCategory(category)?'fresh':'dry'))
  .sort((a,b)=>Number(categoriesWithStock.has(b))-Number(categoriesWithStock.has(a)));
 const groups={dry:document.createDocumentFragment(),fresh:document.createDocumentFragment()};
 const categoriesWithFoods=new Set(data.map(item=>item.category));
 const catalogByCategory=new Map();
 const addCatalogNames=(name,names)=>{
  const category=findPantryCategory(name)?.nombre??name;
  const key=categoryIdentity(category);
  const entries=catalogByCategory.get(key)??new Map();
  for(const food of names)entries.set(folded(food),food);
  catalogByCategory.set(key,entries);
 };
 for(const [name,foods] of Object.entries(freshCatalogGroups))addCatalogNames(name,foods);
 if(catalogRows.length){
  for(const row of catalogRows)addCatalogNames(row.categoria,[row.nombre]);
 }else{
  for(const [name,foods] of Object.entries(initial))addCatalogNames(name,foods);
 }
 // La preferencia de orden se conserva en el selector oculto; las flechas son el control visible.
 foodGroupOrder.hidden=true;
 for(const category of categories){
  const group=isFreshCategory(category)?'fresh':'dry';
  const inactive=!isFoodGroupVisible(group)&&!categoriesWithStock.has(category);
  const rows=shown.filter(x=>x.category===category);
  if(!categoriesWithFoods.has(category)){
   const catalog=catalogByCategory.get(categoryIdentity(category));
   for(const name of catalog?.values()??[]){
    if(folded(name).includes(q))rows.push({name,category,have:false,catalog});
   }
  }
  rows.sort((a,b)=>esCompare(a.name,b.name));
  if(q&&!rows.length)continue;
  const details=document.createElement('details');details.className='category';details.open=openCategories.has(category)||!!q;
  details.classList.toggle('inactive-food-category',inactive);
  if(!q)details.addEventListener('toggle',()=>{
   if(details.open)openCategories.add(category);
   else openCategories.delete(category);
  });
  details.append(categoryHeader(category,`${rows.filter(x=>x.have).length}/${rows.length}`,
   pantryCategoryByName.get(category)?.icono,!categoriesWithStock.has(category)));
  details.append(categoryAddFoodForm(category,false));
  for(const x of rows){
   const row=document.createElement('div');row.className='item'+(x.have?' done':'');
   row.classList.toggle('inactive-category-item',!categoriesWithStock.has(category));
   const check=foodAvailabilityCheckbox(x);
   const name=document.createElement('span');name.textContent=x.name;row.append(check,name);details.append(row);
  }
  groups[group].append(details);
 }
 const groupOrder=(foodGroupOrder.value==='fresh'?['fresh','dry']:['dry','fresh'])
  .filter(group=>vintage?groups[group].childElementCount:
   !isFoodGroupVisible(group)||categories.some(category=>isFreshCategory(category)===(group==='fresh')));
 if(!vintage)groupOrder.sort((a,b)=>Number(isFoodGroupVisible(b))-Number(isFoodGroupVisible(a)));
 if(!vintage&&!groupOrder.length){
  const empty=document.createElement('p');empty.className='empty';
  empty.textContent='No hay alimentos con este filtro.';
  main.append(empty);
 }
 const useDoors=vintage&&pantryStylePreference('start_fridge_closed')===true&&!q;
 main.classList.toggle('fridge-with-doors',useDoors&&groupOrder.length>0);
 const allDoorsClosed=groupOrder.every(group=>!openedFridgeDoors.has(group));
 main.classList.toggle('fridge-all-doors-closed',useDoors&&groupOrder.length>0&&allDoorsClosed);
 const displayedGroups=vintage?groupOrder:[groupOrder.find(group=>group===visibleFoodGroup)??groupOrder[0]].filter(Boolean);
 for(const [index,group] of displayedGroups.entries()){
  const title=document.createElement('h2');
  title.className='food-group-title';
  const groupName=group==='fresh'?'Alimentos frescos':'Alimentos secos';
  const groupLabel=document.createElement('span');
  groupLabel.textContent=groupName;
  groupLabel.classList.toggle('inactive-food-label',!isFoodGroupVisible(group));
  title.append(groupLabel);
  title.id='food-group-'+group;
  title.tabIndex=-1;
  if(useDoors){
   const door=document.createElement('button');
   door.type='button';
   door.id='fridge-door-'+group;
   door.setAttribute('aria-expanded',String(openedFridgeDoors.has(group)));
   if(!openedFridgeDoors.has(group)){
    door.className='fridge-door'+(groupOrder.length===1?' fridge-door-single':'');
    const plate=document.createElement('span');
    plate.textContent=groupName;
    door.append(plate);
    door.onclick=()=>{
     openedFridgeDoors.add(group);
     render();
     $(title.id).focus({preventScroll:true});
    };
    main.append(door);
    continue;
   }
   door.className='fridge-close-door';
   door.textContent='×';
   door.setAttribute('aria-label','Cerrar puerta de '+groupName.toLowerCase());
   door.onclick=()=>{
    openedFridgeDoors.delete(group);
    render();
    $(door.id).focus({preventScroll:true});
   };
   title.append(door);
  }
  if(groupOrder.length===2){
   const target=group==='fresh'?'dry':'fresh';
   const jump=document.createElement('button');
   jump.type='button';
   jump.className='food-group-jump';
   jump.textContent=index===0?'↓':'↑';
   const groupName=group==='fresh'?'alimentos frescos':'alimentos secos';
   jump.title='Mover '+groupName+(index===0?' abajo':' arriba');
   jump.setAttribute('aria-label',jump.title);
   jump.onclick=()=>{
    foodGroupOrder.value=target==='fresh'?'fresh':'dry';
    foodGroupOrder.onchange();
    $('food-group-'+group).querySelector('.food-group-jump').focus({preventScroll:true});
   };
   if(!vintage){
    const targetName=target==='fresh'?'frescos':'secos';
    jump.className='food-group-switch';
    jump.textContent=targetName;
    jump.classList.toggle('inactive-food-switch',!isFoodGroupVisible(target));
    jump.title='Consultar alimentos '+targetName;
    jump.setAttribute('aria-label',jump.title);
    jump.onclick=()=>{
     visibleFoodGroup=target;
     render();
     $('food-group-'+target).querySelector('.food-group-switch').focus({preventScroll:true});
    };
   }
   title.append(jump);
  }
  if(useDoors){
   const compartment=document.createElement('section');
   compartment.className='fridge-compartment';
   compartment.setAttribute('aria-labelledby',title.id);
   compartment.append(title,groups[group]);
   main.append(compartment);
  }else{
   if(!vintage&&!groups[group].childElementCount){
    const empty=document.createElement('p');empty.className='empty';
    empty.textContent=q?'No hay alimentos con este filtro.':'Este grupo todavía no tiene categorías.';
    groups[group].append(empty);
   }
   main.append(title,groups[group]);
  }
 }
 if(useDoors&&groupOrder.length&&(pantryStylePreference('fridge_notes_enabled')===true||pantryStylePreference('automatic_pantry_note_enabled')===true)){
  renderFridgeNotes(main,groupOrder,allDoorsClosed);
 }
 if(adminMode)renderAdmin();
}
async function refresh(setup=null){
 if(!session||!activePantry||(basicSetup?.saving&&setup!==basicSetup))return;
 const pantryId=activePantry.id;
 const version=++refreshVersion;
 const [food,categories]=await Promise.all([
  db.from('alimentos').select('id,nombre,categoria,categoria_id,disponible').eq('despensa_id',pantryId).order('creado_en',{ascending:true}),
  db.from('categorias_despensa').select('id,nombre,icono,nombres_anteriores').eq('despensa_id',pantryId).order('id')
 ]);
 if(version!==refreshVersion||!session)return;
 const {data:rows}=food,error=food.error??categories.error;
 if(error){
  if(setup)throw error;
  setStatus('Sin conexión o sin permisos: '+error.message);
  $('auth').hidden=false;$('status').hidden=false;
  return;
 }
 const nextCategories=new Map(categories.data.map(row=>[row.nombre,row]));
 const namesById=new Map(categories.data.map(row=>[row.id,row.nombre]));
 const next=rows.map(x=>({id:x.id,name:x.nombre,category:namesById.get(x.categoria_id)??x.categoria,have:pendingCategoryAvailability?.pantryId===pantryId&&pendingCategoryAvailability.ids.has(x.id)
  ?pendingCategoryAvailability.available:!!x.disponible}));
 const changed=JSON.stringify(next)!==JSON.stringify(data)||
  JSON.stringify([...nextCategories.values()])!==JSON.stringify([...pantryCategoryByName.values()]);
 pantryCategoryByName=nextCategories;
 data=next;if(changed)render();
 setStatus('☁️ Lista compartida · '+data.length+' alimentos · Sincronizada');
 $('migration').hidden=data.length!==0||pantrySystemKey(activePantry)!=='playa';
 $('auth').hidden=$('migration').hidden;
 $('status').hidden=$('migration').hidden;
 return true;
}
