function canManagePantry(pantry){
 return !pantrySystemKey(pantry)||session?.user?.id==='d0f8ab40-f2ea-43e5-9bd0-d7cebdd1fa59';
}
let removingPantry=false;
async function removePantry(pantry,button,status){
 const current=session;
 if(!pantry||!current||button.disabled||removingPantry)return;
 if(!canManagePantry(pantry)){
  status.textContent='Tu cuenta no puede eliminar «'+pantry.nombre+'».';
  return;
 }
 removingPantry=true;
 button.disabled=true;
 const fromChooser=pantryChooser.contains(button);
 let protectionRemoved=false;
 if(fromChooser)pantryChooser.inert=true;
 try{
  status.textContent='Comprobando la protección…';
  const {data:protectedState,error:protectionError}=await db.rpc('proteccion_borrado_despensa',{
   p_despensa_id:pantry.id,p_proteger:null
  });
  if(session!==current)return;
  if(protectionError)throw protectionError;
  if(typeof protectedState!=='boolean')throw new Error('No se pudo comprobar la protección.');
  if(protectedState&&!fromChooser){
   status.textContent='«'+pantry.nombre+'» está protegida. Desactiva la protección en Administrar → Despensa actual.';
   return;
  }
  status.textContent='';
  const action=protectedState?'Quitar la protección y eliminar':'Eliminar';
  if(!confirm('¿'+action+' «'+pantry.nombre+'»? Se borrarán sus alimentos y categorías. Esta acción es definitiva.'))return;
  status.textContent='Eliminando despensa…';
  if(protectedState){
   const {data,error}=await db.rpc('proteccion_borrado_despensa',{p_despensa_id:pantry.id,p_proteger:false});
   if(error)throw error;
   if(data!==false)throw new Error('No se pudo quitar la protección.');
   protectionRemoved=true;
  }
  if(session!==current)return;
  const {error}=await db.rpc('eliminar_despensa_personal',{p_despensa_id:pantry.id});
  if(error)throw error;
  protectionRemoved=false;
  if(session!==current)return;
  pantryReloadSelection(null);
  await signedIn(current);
 }catch(error){
  if(session!==current)return;
  let message='No se pudo eliminar: '+error.message;
  if(protectionRemoved){
   try{
    const result=await db.rpc('proteccion_borrado_despensa',{p_despensa_id:pantry.id,p_proteger:true});
    if(result.error||result.data!==true)throw new Error('Protección sin confirmar.');
   }catch{
    message+=' No se pudo confirmar que la protección se haya reactivado.';
   }
  }
  if(session===current)status.textContent=message;
 }finally{
  removingPantry=false;
  button.disabled=false;
  if(fromChooser){
   pantryChooser.inert=false;
   if(button.isConnected&&!pantryChooser.hidden)button.focus();
  }
 }
}
deletePantryButton.onclick=()=>removePantry(activePantry,deletePantryButton,deletePantryStatus);

async function signedIn(currentSession,restorePantry=false){
 if($('basicSetupDialog').open)$('basicSetupDialog').close();
 session=currentSession;
 activePantry=null;
 applyPantryPostcard(null);
 availablePantries=[];
 pantryChooser.hidden=true;
 switchPantry.hidden=true;
 recentAdminFoods.clear();
 applyAlternateHome(currentSession?.user?.user_metadata?.alternate_home);
 $('alternateHomeMessage').textContent='';
 applyViewStyle(currentSession?.user?.user_metadata?.view_style);
 $('iconMessage').textContent='';
 $('typographyMessage').textContent='';
 const preferences=currentSession?.user?.user_metadata;
 let lastBackground;
 if(currentSession){
  try{lastBackground=JSON.parse(localStorage.getItem('hondadespensa:fondo:'+currentSession.user.id))?.preference;}catch{}
 }
 const restoredPantryId=restorePantry?pantryReloadSelection():null;
 applyBackground(lastBackground??preferences?.['app_background_'+restoredPantryId]
  ??preferences?.chooser_background??preferences?.app_background);
 $('backgroundMessage').textContent='';
 categoryOrder=readCategoryOrder(currentSession?.user?.user_metadata?.category_order);
 refreshVersion++;
 pantryCategoryByName=new Map();
 data=[];
 showApp(false);
 $('loginForm').hidden=!!currentSession;
 if(channel){await db.removeChannel(channel);channel=null;}
 if(catalogChannel){await db.removeChannel(catalogChannel);catalogChannel=null;}
 if(!currentSession){setStatus('Inicia sesión con tu cuenta de HondaDespensa.');$('auth').hidden=false;$('status').hidden=false;$('loginForm').hidden=false;return;}
 const u=currentSession.user||{};
 $('accountName').textContent=u.user_metadata?.display_name||u.user_metadata?.full_name||u.email?.split('@')[0]||'Usuario';
 setStatus('Cargando despensas…');
 let {data:pantries,error}=await db.rpc('listar_mis_despensas');
 if(error?.code==='PGRST202'){
  ({data:pantries,error}=await db.from('despensas').select('*').order('nombre'));
 }
 if(session!==currentSession)return;
 if(error){
  setStatus('No se pudieron cargar las despensas: '+error.message);
  $('loginForm').hidden=false;
  return;
 }
 availablePantries=pantries;
 restoreHomeCardRemoval();
 const selectedId=restorePantry?pantryReloadSelection():null;
 const selected=pantries.find(pantry=>pantry.id===selectedId);
 if(selected||pantries.length===1)await openPantry(selected??pantries[0]);
 else choosePantry(Boolean(lastBackground));
 await loadCatalog();
 if(session!==currentSession)return;
 channel=db.channel('alimentos-honda-v21').on('postgres_changes',{event:'*',schema:'public',table:'alimentos'},()=>refresh()).subscribe();
 catalogChannel=db.channel('catalogo-honda-v21').on('postgres_changes',{event:'*',schema:'public',table:'catalogo'},()=>loadCatalog()).subscribe();
}

