const freshCatalogOpen=new Set();
function renderCatalog(){
 const groups=catalogReady?Object.entries(catalogRows.reduce((acc,x)=>{(acc[x.categoria]??=[]).push(x.nombre);return acc;},{})):Object.entries(initial);
 renderCatalogList($('catalogItems'),$('catalogSearch'),groups,catalogOpen);
 if($('freshCatalogItems')){
  renderCatalogList($('freshCatalogItems'),$('freshCatalogSearch'),Object.entries(freshCatalogGroups),freshCatalogOpen);
 }
}
function renderCatalogList(holder,search,groups,openCategories){
 const q=folded(search.value.trim());
 holder.replaceChildren();
 let remaining=0;
 for(const [category,names] of groups.sort((a,b)=>esCompare(a[0],b[0]))){
  const existingCategory=findPantryCategory(category);
  const available=names.filter(name=>!data.some(x=>x.category===(existingCategory?.nombre??category)&&folded(x.name)===folded(name))&&folded(name).includes(q));
  if(!available.length)continue;remaining+=available.length;
  const details=document.createElement('details');details.className='catalog-category';details.open=openCategories.has(category)||!!q;
  if(!q)details.addEventListener('toggle',()=>{if(details.open)openCategories.add(category);else openCategories.delete(category)});
  const summary=document.createElement('summary');
  if(holder.id==='freshCatalogItems'){
   const art=freshCategoryArt[freshCategoryIcon(category)];
   if(art){
    const image=categoryIcon(category);
    image.classList.add('fresh-catalog-icon');
    summary.append(image);
   }
  }
  summary.append(bareCategory(category)+' · '+available.length);
  details.append(summary);
  const products=document.createElement('div');products.className='catalog-products';
  const addAll=document.createElement('button');
  addAll.type='button';
  addAll.textContent=q?'＋ Añadir todos de la categoría':'＋ Añadir todos';
  const addCategory=selectedNames=>{
   if(addingCatalogCategory)return;
   for(const button of document.querySelectorAll('#catalogItems button,#freshCatalogItems button'))button.disabled=true;
   addCatalogCategory(category,selectedNames);
  };
  addAll.disabled=addingCatalogCategory;
  addAll.onclick=()=>addCategory(names);
  products.append(addAll);
  if(!existingCategory){
   const addEmpty=document.createElement('button');
   addEmpty.type='button';addEmpty.className='secondary';
   addEmpty.textContent='＋ Añadir solo la categoría';
   addEmpty.disabled=addingCatalogCategory;
   addEmpty.onclick=()=>addCategory([]);
   products.append(addEmpty);
  }
  for(const name of available){
   const button=document.createElement('button');button.type='button';button.textContent='＋ '+name;
   button.disabled=addingCatalogCategory;
   button.onclick=async()=>{
    button.disabled=true;
    const categoryName=findPantryCategory(category)?.nombre??category;
    if(!await addSharedFood(name,categoryName)){
     button.disabled=false;
     return;
    }
    await showCatalogFoodGroup(categoryName);
    renderCatalog();
   };
   products.append(button);
  }
  details.append(products);holder.append(details);
 }
 if(!remaining){const p=document.createElement('p');p.className='empty';p.textContent=q?'No hay alimentos disponibles con esa búsqueda.':'Todos los alimentos del catálogo ya están añadidos.';holder.append(p);}
}
function foodAvailabilityCheckbox(item){
 const check=document.createElement('input');check.type='checkbox';check.checked=item.have;check.disabled=busy||(pendingCategoryAvailability?.pantryId===activePantry?.id&&pendingCategoryAvailability?.ids.has(item.id));
 check.setAttribute('aria-label','Tengo '+item.name);
 if(item.catalog){
  check.onchange=async()=>{
   check.disabled=true;
   openCategories.add(item.category);
   if(await addCatalogCategory(item.category,item.catalog.values(),{markedName:item.name}))return;
   check.checked=false;
   check.disabled=false;
  };
  return check;
 }
 check.onchange=async()=>{
  check.disabled=true;
  const {error}=await db.from('alimentos').update({disponible:check.checked}).eq('id',item.id).eq('despensa_id',activePantry.id);
  if(error)alert('No se pudo guardar: '+error.message);
  await refresh();
 };
 return check;
}
function makeAdminRow(item,type){
 const row=document.createElement('div');row.className=type==='food'?'admin-row admin-food-row':'admin-row';
 const label=document.createElement(type==='food'?'label':'div');label.className='admin-label';
 if(type==='food'){
  label.append(foodAvailabilityCheckbox(item));
 }
 const name=document.createElement('strong');name.textContent=type==='food'?item.name:item.nombre;
 label.append(name);
 const actions=document.createElement('div');actions.className='admin-actions';
 const edit=document.createElement('button');edit.type='button';edit.className='secondary';edit.textContent='Editar';
 const del=document.createElement('button');del.type='button';del.className='danger';del.textContent='Eliminar';
 if(type==='food'){
  setAdminIcon(edit,'edit','Editar '+item.name);
  setAdminIcon(del,'trash','Eliminar '+item.name);
 }
 actions.append(edit,del);row.append(label,actions);
 edit.onclick=()=>{
  if(row.querySelector('.admin-edit')){row.querySelector('.admin-edit').remove();return;}
  const form=document.createElement('form');form.className='admin-edit';
  const n=document.createElement('input');n.required=true;n.maxLength=100;n.value=type==='food'?item.name:item.nombre;n.setAttribute('aria-label','Nombre del alimento');
  const save=document.createElement('button');save.type='submit';save.textContent='Guardar cambios';form.append(n,save);row.append(form);
  form.onsubmit=async e=>{
   e.preventDefault();const nombre=n.value.trim();if(!nombre)return;
   save.disabled=true;
   const table=type==='food'?'alimentos':'catalogo';
   const {error}=await db.from(table).update({nombre}).eq('id',item.id);
   if(error){adminMessage('Error: '+error.message);save.disabled=false;return;}
   await refresh();if(type==='catalog')await loadCatalog();adminMessage('Cambios guardados.');
  };
 };
 del.onclick=async()=>{
  if(!confirm('¿Eliminar «'+(type==='food'?item.name:item.nombre)+'» '+(type==='food'?'de la despensa':'del catálogo')+'?'))return;
  del.disabled=true;
  const {error}=await db.from(type==='food'?'alimentos':'catalogo').delete().eq('id',item.id);
  if(error){adminMessage('Error: '+error.message);del.disabled=false;return;}
  await refresh();if(type==='catalog')await loadCatalog();
  adminMessage('Alimento eliminado.');
 };
 return row;
}
const categoryFoodDrafts=new Map(),categoryFoodSaving=new Set();
function categoryAddFoodForm(category,inAdmin=true){
 const form=document.createElement('form');form.className='add category-add-food'+(inAdmin?'':' pantry-quick-add');
 if(!inAdmin)form.style.cssText='padding:10px 12px;margin:0;border-top:1px solid #476581';
 form.setAttribute('aria-label','Añadir alimento en '+bareCategory(category));
 const input=document.createElement('input');input.type='text';input.required=true;input.maxLength=100;
 input.placeholder=inAdmin?'Nuevo alimento':'Añadir a esta categoría';input.setAttribute('aria-label','Nombre del nuevo alimento en '+bareCategory(category));
 input.value=categoryFoodDrafts.get(category)||'';
 input.oninput=()=>categoryFoodDrafts.set(category,input.value);
 const button=document.createElement('button');button.type='submit';button.textContent='Añadir';
 if(inAdmin)setAdminIcon(button,'add','Añadir alimento');
 input.disabled=button.disabled=categoryFoodSaving.has(category);
 form.append(input,button);
 form.onsubmit=async event=>{
  event.preventDefault();const name=input.value.trim();
  if(!name||categoryFoodSaving.has(category))return;
  categoryFoodDrafts.set(category,input.value);categoryFoodSaving.add(category);
  input.disabled=button.disabled=true;
  if(!inAdmin)button.textContent='Añadiendo…';
  try{
   if(await addSharedFood(name,category,inAdmin)){
    categoryFoodDrafts.delete(category);
    if(inAdmin)adminMessage('Alimento añadido en '+bareCategory(category)+'.');
   }
  }catch(error){
   const message='No se pudo añadir: '+error.message;
   if(inAdmin)adminMessage(message);else alert(message);
  }
  finally{
   categoryFoodSaving.delete(category);
   if(inAdmin){
    renderAdmin();
   const section=[...$('adminFoods').querySelectorAll('details.admin-category')].find(x=>x.dataset.category===category);
    section?.querySelector('.category-add-food input')?.focus();
   }else render();
  }
 };
 return form;
}

function foodGroupEyeIcon(visible){
 const ns='http://www.w3.org/2000/svg';
 const svg=document.createElementNS(ns,'svg');
 for(const [name,value] of Object.entries({
  viewBox:'0 0 24 24',width:'21',height:'21',fill:'none',stroke:'currentColor',
  'stroke-width':'1.8','stroke-linecap':'round','stroke-linejoin':'round','aria-hidden':'true'
 }))svg.setAttribute(name,value);
 const eye=document.createElementNS(ns,'path');
 eye.setAttribute('d','M2 12s3.6-7 10-7 10 7 10 7-3.6 7-10 7S2 12 2 12Z');
 svg.append(eye);
 const pupil=document.createElementNS(ns,'circle');
 pupil.setAttribute('cx','12');pupil.setAttribute('cy','12');pupil.setAttribute('r','3');
 svg.append(pupil);
 if(!visible){
  const slash=document.createElementNS(ns,'path');
  slash.setAttribute('d','M3 3l18 18');
  svg.append(slash);
 }
 return svg;
}
function renderGroupedAdmin(container,rows,type,query){
 const open=adminOpenCategories[type];
 // Leer el estado actual antes de reconstruir la lista, sin esperar al evento toggle.
 for(const section of container.querySelectorAll('details.admin-category')){
  // No recordar las aperturas temporales provocadas por la búsqueda.
  if(type==='food'&&container.dataset.query)continue;
  if(section.open)open.add(section.dataset.category);else open.delete(section.dataset.category);
 }
 // El estado de los grupos se guarda cuando el usuario toca su flecha.
 if(type==='food')container.dataset.query=query;
 container.replaceChildren();const groups=new Map();
 const categoriesWithStock=type==='food'?new Set(rows.filter(item=>item.have).map(item=>item.category)):null;
 if(type==='food')for(const category of pantryCategories())if(!query||folded(category).includes(query))groups.set(category,[]);
 for(const item of rows){
  const category=type==='food'?item.category:item.categoria;
  const name=type==='food'?item.name:item.nombre;
  if(!folded(name+' '+category).includes(query))continue;
  if(!groups.has(category))groups.set(category,[]);
  groups.get(category).push(item);
 }
 const foodGroups=new Map();
 const categories=type==='food'?orderedCategories(groups.keys()):[...groups.keys()].sort(esCompare);
 for(const category of categories){
  const section=document.createElement('details');section.className='category admin-category';
  const count=groups.get(category).length;
  const header=categoryHeader(category,type==='food'?String(count):count+' alimentos',
   type==='food'?pantryCategoryByName.get(category)?.icono:undefined,
   type==='food'&&!categoriesWithStock.has(category));
  if(type==='food')header.querySelector('.cat-count').setAttribute('aria-label',count+' alimentos');
  section.append(header);
  if(type==='food')section.append(categoryManagement(category),categoryAddFoodForm(category));
  for(const item of groups.get(category).sort(type==='food'?compareAdminFoods:(a,b)=>esCompare(a.nombre,b.nombre)))section.append(makeAdminRow(item,type));
  section.dataset.category=category;
  section.open=open.has(category)||!!query;
  if(type==='catalog'){
   container.append(section);
   continue;
  }
  const group=isFreshCategory(category)?'fresh':'dry';
  if(!foodGroups.has(group)){
   const shell=document.createElement('section');
   shell.className='admin-food-group-flat';
   shell.dataset.foodGroup=group;
   const cards=document.createElement('div');
   cards.className='admin-food-category-cards';
   cards.id='admin-food-group-'+group+'-cards';
   shell.append(cards);
   foodGroups.set(group,{shell,cards,count:0});
  }
  const foodGroup=foodGroups.get(group);
  foodGroup.cards.append(section);
  foodGroup.count+=count;
 }
 const orderedGroups=(foodGroupOrder.value==='fresh'?['fresh','dry']:['dry','fresh'])
  .filter(group=>foodGroups.has(group))
  .sort((a,b)=>Number(isFoodGroupVisible(b))-Number(isFoodGroupVisible(a)));
 for(const group of orderedGroups){
  const foodGroup=foodGroups.get(group);
  if(!foodGroup)continue;
  const title=group==='dry'?'Alimentos secos':'Alimentos frescos';
  const original=categoryHeader(title,String(foodGroup.count));
  original.querySelector('.cat-icon')?.remove();
  original.querySelector('.chevron')?.remove();
  const header=document.createElement('div');
  header.className='category-header admin-food-group-bar';
  header.append(...original.childNodes);
  header.querySelector('.cat-count').setAttribute('aria-label',foodGroup.count+' alimentos');
  const expanded=!!query||(adminFoodGroupOpen.get(group)??false);
  foodGroup.cards.hidden=!expanded;
  const collapse=document.createElement('button');
  collapse.type='button';
  collapse.className='admin-icon-button admin-food-group-collapse';
  collapse.setAttribute('aria-controls',foodGroup.cards.id);
  collapse.setAttribute('aria-label',(expanded?'Plegar ':'Desplegar ')+title.toLowerCase());
  collapse.setAttribute('aria-expanded',String(expanded));
  collapse.onclick=()=>{
   const next=foodGroup.cards.hidden;
   foodGroup.cards.hidden=!next;
   adminFoodGroupOpen.set(group,next);
   collapse.setAttribute('aria-label',(next?'Plegar ':'Desplegar ')+title.toLowerCase());
   collapse.setAttribute('aria-expanded',String(next));
  };
  header.append(collapse);
  const visible=isFoodGroupVisible(group);
  const eye=document.createElement('button');
  eye.type='button';
  eye.className='admin-icon-button food-group-eye';
  eye.setAttribute('aria-label',(visible?'Ocultar ':'Mostrar ')+title.toLowerCase()+' en la despensa');
  eye.setAttribute('aria-pressed',String(visible));
  eye.title=eye.getAttribute('aria-label');
  eye.disabled=savingFoodGroupVisibility;
  eye.append(foodGroupEyeIcon(visible));
  eye.onclick=event=>{
   event.preventDefault();
   event.stopPropagation();
   saveFoodGroupVisibility(group,!visible);
  };
  const all=document.createElement('label');
  all.className='admin-category-all admin-group-all';
  const allCheck=document.createElement('input');
  allCheck.type='checkbox';
  // "Todos" modifica el grupo completo, incluso si hay un filtro de búsqueda.
  const allItems=data.filter(item=>(isFreshCategory(item.category)?'fresh':'dry')===group);
  const selected=allItems.filter(item=>item.have).length;
  allCheck.checked=allItems.length>0&&selected===allItems.length;
  allCheck.indeterminate=selected>0&&selected<allItems.length;
  allCheck.disabled=!!pendingCategoryAvailability||busy||!allItems.length;
  allCheck.setAttribute('aria-label','Marcar o desmarcar todos los '+title.toLowerCase());
  all.title=allCheck.getAttribute('aria-label');
  all.append(allCheck,document.createTextNode('Todos'));
  // El clic del control masivo nunca abre ni cierra el grupo.
  all.onclick=event=>event.stopPropagation();
  all.onkeydown=event=>event.stopPropagation();
  allCheck.onchange=()=>setBulkFoodAvailability(allItems,allCheck.checked,title.toLowerCase());
  const move=document.createElement('button');
  move.type='button';
  move.className='admin-food-group-move';
  const moveDown=group===orderedGroups[0];
  const direction=moveDown?'abajo':'arriba';
  setAdminIcon(move,moveDown?'down':'up','Mover '+title.toLowerCase()+' '+direction);
  move.hidden=orderedGroups.length<2||isFoodGroupVisible(orderedGroups[0])!==isFoodGroupVisible(orderedGroups[1]);
  move.onclick=event=>{
   event.preventDefault();
   event.stopPropagation();
   foodGroupOrder.value=foodGroupOrder.value==='fresh'?'dry':'fresh';
   foodGroupOrder.onchange(); // Guarda en la despensa y reordena la nevera y el administrador.
   container.querySelector('.admin-food-group-flat[data-food-group="'+group+'"] .admin-food-group-move')
    ?.focus({preventScroll:true});
  };
  const actions=document.createElement('div');
  actions.className='admin-food-group-actions';
  actions.append(all,eye,move);
  header.append(actions);
  foodGroup.shell.classList.toggle('is-hidden-group',!visible);
  foodGroup.shell.prepend(header);
  container.append(foodGroup.shell);
 }
 if(!groups.size){const p=document.createElement('p');p.className='empty';p.textContent='No hay alimentos con este filtro.';container.append(p);}
}
